def special_permutations(nums):
    total_permutations = 0
    for i in range(nums.length):
        if nums[i] % nums[i+1] == 0 or nums[i+1] % nums[i] == 0:
            total_permutations += 1
    return total_permutations

def sum_imbalance(nums):
    sum = 0
    for i in range(nums.length):
        if nums[i] > nums[i+1]:
            sum += nums[i+1] - nums[i]
        else:
            sum += nums[i]
    return sum

