def find_max_sum(nums):
    balanced_subsequence = [i for i in range(nums.length - 1)]
    max_sum = 0
    for j in range(nums.length - 1):
        if balanced_subsequence[j] - balanced_subsequence[j-1] >= balanced_subsequence[j-1] - balanced_subsequence[j]:
            max_sum = max(max_sum, max(balanced_subsequence[j], balanced_subsequence[j-1]))
    return max_sum

