def is_connected_to_neighbors(vertex):
    if not vertex:
        return 0
    for neighbor in vertex.get_neighbors():
        if neighbor.is_connected_to(vertex):
            return 1
    return 0

def is_similar(s, t):
    if not s.isalnum() or not t.isalnum():
        return False
    for i in range(1, len(s) + 1):
        if s[i] == t[i]:
            return True
    return False

def print_names(n):
    for i in range(1, n):
        print(f"{i} {i} is the person sitting in the {i}th position clockwise from the youngest person.")
    return f"{n} {n} is the person sitting in the {n}th position clockwise from the youngest person."

